package com.ethk3.novaonepro.strategyv2;
import java.io.*;import java.lang.reflect.*;import java.util.*;
public final class R26DistillationDiagnosticsTest {
 static void check(boolean x,String why){if(!x)throw new AssertionError(why);}
 static final class Teacher implements DistillationFamilyR26.Teacher {String id="SYNTHETIC_FIXED_TEACHER";double[][] q;boolean drift;public String identity(){return id;}public double[][] marginal(){if(drift)id="SYNTHETIC_CHANGED_TEACHER";return q;}}
 static byte[] save(DistillationFamilyR26 m)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
 static DistillationFamilyR26 restore(Teacher t,byte[] b)throws Exception{DistillationFamilyR26 m=new DistillationFamilyR26(t);m.read(new DataInputStream(new ByteArrayInputStream(b)));return m;}
 static Object get(DistillationFamilyR26 m,String name)throws Exception{Field f=DistillationFamilyR26.class.getDeclaredField(name);f.setAccessible(true);return f.get(m);}
 static int[] draw(Random r){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int j=r.nextInt(i+1),v=d[i];d[i]=d[j];d[j]=v;}return d;}
 static double loss(DistillationFamilyR26 m,int[] draw,double[][] target)throws Exception{double[][] b=(double[][])get(m,"bias"),c=(double[][])get(m,"context"),s=new double[10][10];int[] previous=(int[])get(m,"previous");double alpha=target==null?0:.35;for(int p=0;p<10;p++)for(int n=0;n<10;n++)s[p][n]=b[p][n]+(previous==null?0:c[p*10+n][previous[p]-1]);double value=ExactPermutationR26.infer(s,null).logZ;for(int p=0;p<10;p++)for(int n=0;n<10;n++)value-=((1-alpha)*(draw[p]==n+1?1:0)+alpha*(target==null?0:target[p][n]))*s[p][n];return value;}
 public static void main(String[] args)throws Exception{
  double maxError=0;int coordinates=0;
  for(int mode=0;mode<3;mode++){Teacher t=new Teacher();if(mode>0){t.q=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++)t.q[p][n]=mode==1?.1:.015+(n==(p+3)%10?.85:0);}
   DistillationFamilyR26 m=new DistillationFamilyR26(t);Random random=new Random(2623+mode);for(int i=0;i<20;i++)m.update(draw(random));byte[] before=save(m);double[][] b=(double[][])get(m,"bias"),c=(double[][])get(m,"context");int[] previous=(int[])get(m,"previous"),target=draw(random);double[] numeric=new double[20];double beforeLoss=loss(m,target,t.q);
   for(int k=0;k<20;k++){int p=k%10,n=(k*7)%10,row=p*10+n,index=previous[p]-1;double old=k<10?b[p][n]:c[row][index];if(k<10)b[p][n]=old+1e-5;else c[row][index]=old+1e-5;double plus=loss(m,target,t.q);if(k<10)b[p][n]=old-1e-5;else c[row][index]=old-1e-5;double minus=loss(m,target,t.q);if(k<10)b[p][n]=old;else c[row][index]=old;numeric[k]=(plus-minus)/2e-5;coordinates++;}
   m.update(target);TrainingDiagnosticsR26.Step step=m.lastTrainingStep();double[][] nb=(double[][])get(m,"bias"),nc=(double[][])get(m,"context");DistillationFamilyR26 fixed=restore(t,before);double[][] fb=(double[][])get(fixed,"bias"),fc=(double[][])get(fixed,"context");for(int i=0;i<10;i++)System.arraycopy(nb[i],0,fb[i],0,10);for(int i=0;i<100;i++)System.arraycopy(nc[i],0,fc[i],0,10);check(Math.abs(beforeLoss-step.lossBefore)<1e-12&&Math.abs(loss(fixed,target,t.q)-step.lossAfter)<1e-12,"fixed teacher/input loss differs");double grad2=0,delta2=0;for(int p=0;p<10;p++)for(int n=0;n<10;n++){double d=nb[p][n]-b[p][n];delta2+=d*d;grad2+=(d/.02)*(d/.02);d=nc[p*10+n][previous[p]-1]-c[p*10+n][previous[p]-1];delta2+=d*d;grad2+=(d/.02)*(d/.02);}check(Math.abs(Math.sqrt(grad2)-step.gradientNorm)<1e-12&&step.parameterDeltaNorm==Math.sqrt(delta2),"actual active-coordinate norms differ");
   for(int k=0;k<20;k++){int p=k%10,n=(k*7)%10;double actual=k<10?(b[p][n]-nb[p][n])/.02:(c[p*10+n][previous[p]-1]-nc[p*10+n][previous[p]-1])/.02;maxError=Math.max(maxError,Math.abs(actual-numeric[k]));check(Math.abs(actual-numeric[k])<1e-8,"expected-score derivative differs");}
   DistillationFamilyR26 alternative=restore(t,before);alternative.update(draw(random));check(step.inputHash.equals(alternative.lastTrainingStep().inputHash),"label leaked into hash");DistillationFamilyR26 copy=restore(t,save(m));check(copy.lastTrainingStep()==null,"restore fabricated training");target=draw(random);m.update(target);copy.update(target);check(Arrays.equals(save(m),save(copy)),"restored next differs");long updates=m.completedTrainingUpdates();m.resetTemporalContext();check(m.completedTrainingUpdates()==updates&&m.lastTrainingStep()==null,"gap erased lifetime");copy=restore(t,save(m));target=draw(random);m.update(target);copy.update(target);check(Arrays.equals(save(m),save(copy)),"gap restore differs");byte[] good=save(m);
   for(int k=0;k<2;k++){byte[] bad=good.clone();if(k==0)bad=Arrays.copyOf(bad,bad.length-1);else bad[6]='x';try{m.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("bad state accepted");}catch(IOException expected){}check(Arrays.equals(good,save(m)),"bad restore damaged state");}
   for(int budget:new int[]{1,20,150}){m=restore(t,good);ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,budget,()->false));boolean yielded=false;try{m.update(target);}catch(BudgetTokenSU1.Yield expected){yielded=true;}finally{ExecutionBudgetR26.leave();}check(yielded&&Arrays.equals(good,save(m))&&m.lastTrainingStep()==null,"interrupted student committed partial state");}
   m=restore(t,good);double[][] original=t.q;t.q=new double[10][];try{m.update(target);throw new AssertionError("malformed teacher accepted");}catch(IllegalArgumentException expected){}check(Arrays.equals(good,save(m)),"bad teacher changed student");t.q=original;t.drift=true;try{m.update(target);throw new AssertionError("drifting teacher accepted");}catch(IllegalStateException expected){}check(Arrays.equals(good,save(m)),"teacher drift partly committed");t.drift=false;t.id="SYNTHETIC_FIXED_TEACHER";
   if(args.length>0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0],"mode-"+mode+".bin"),good);
  }
  System.out.println("R26_DISTILLATION_DIAGNOSTICS_PASS|teacherModes=3|finiteDifferenceCoordinates="+coordinates+"|maximumGradientError="+maxError+"|fixedTeacherProjectionAndPreLabelContext=true|teacherNotCalibratedHitProbability=true|restoreGapCancelAndTeacherDriftAtomic=true|scope=SYNTHETIC_NOT_NATURAL_QUALITY");
 }
}
